class BottleOwnershipKind(str, Enum):
    MEMBERSHIP = "MEMBERSHIP"
    ASSIGNMENT_SHARED = "ASSIGNMENT_SHARED"


@dataclass(frozen=True)
class ProductReference:
    kind: ProductReferenceKind
    reference_id: str
    presentation_reference_id: Optional[str] = None


@dataclass(frozen=True)
class BottleCustodyContext:
    assignment_id: str
    ownership_kind: BottleOwnershipKind
    owner_membership_id: Optional[str] = None
    current_physical_cava_id: Optional[str] = None


@dataclass(frozen=True)
class IndividualBottleIdentity:
    bottle_id: str
    product: ProductReference
    custody: BottleCustodyContext


def validate_product_reference(product: ProductReference) -> None:
    if not str(product.reference_id or "").strip():
        raise ValueError("ProductReference requiere reference_id")


def validate_custody_context(custody: BottleCustodyContext) -> None:
    if not str(custody.assignment_id or "").strip():
        raise ValueError("BottleCustodyContext requiere assignment_id")
    if custody.ownership_kind == BottleOwnershipKind.MEMBERSHIP:
        if not str(custody.owner_membership_id or "").strip():
            raise ValueError("MEMBERSHIP requiere owner_membership_id")
        return
    if custody.ownership_kind == BottleOwnershipKind.ASSIGNMENT_SHARED:
        if custody.owner_membership_id not in (None, ""):
            raise ValueError("ASSIGNMENT_SHARED no debe atribuirse a una membresia individual")
        return
    raise ValueError("ownership_kind no soportado")


def validate_individual_bottle_identity(identity: IndividualBottleIdentity) -> None:
    if not str(identity.bottle_id or "").strip():
        raise ValueError("IndividualBottleIdentity requiere bottle_id")
    validate_product_reference(identity.product)
    validate_custody_context(identity.custody)


